        // Builds a catalog subtree element from its verbatim attributes (id included at its file position, so
        // a vendor element that writes id after another attribute round-trips byte-faithfully). The id token
        // parses the ElementId; placeholder ids are re-minted in place by the insert transform / id stamping.
        private static ProjectElement ElRaw(string tag, (string, string)[] attrs, params ProjectElement[] children)
        {
            string? idToken = null;
            foreach ((string name, string value) in attrs)
            {
                if (name == "id") { idToken = value; break; }
            }
            ElementId? id = idToken is not null && ElementId.TryParse(idToken, out ElementId parsed) ? parsed : null;
            return new ProjectElement(tag, id, attrs.ToImmutableArray(), children.ToImmutableArray());
        }
    }
